package com.runloyal.booking.context; import com.runloyal.booking.domain.AppUser; import com.runloyal.booking.repo.Repos; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.stereotype.*; import java.util.*;
@Component public class TenantContext { private final Repos.Users users; public TenantContext(Repos.Users users){this.users=users;} public AppUser user(){var a=SecurityContextHolder.getContext().getAuthentication(); if(a==null||!(a.getPrincipal() instanceof Jwt jwt)) throw new Forbidden("Authentication required"); return users.findByOktaSubject(jwt.getSubject()).filter(u->u.status==com.runloyal.booking.domain.Model.Status.ACTIVE).orElseThrow(()->new Forbidden("No active tenant membership"));} public UUID tenantId(){return user().tenantId;} public void requireAdmin(){if(user().role!=com.runloyal.booking.domain.Model.Role.TENANT_ADMIN)throw new Forbidden("Tenant admin role required");} public static class Forbidden extends RuntimeException{public Forbidden(String m){super(m);}} }
